+        const voor = s < (dot(c.a, regel.D) + dot(c.b, regel.D)) / 2;
+        beste = { line: l, offset: voor ? o : o + 1 };
+      }
+    });
+  });
+  return beste ? indexOf(model, beste.line, beste.offset) : 0;
+}

