+
+/** Sleutel (mapnaam) van de momentopname van één document in één sessie. */
+export function sleutelVoor(instantieId, sessie, docId) {
+  return `${veiligDeel(instantieId, 40)}_${veiligDeel(sessie, 8)}_${veiligDeel(docId, 60)}`;
